class Solution:
    def longestFibonacciSubarray(self, nums: list[int]) -> int:
        best = cur = 2
        for i in range(2, len(nums)):
            if nums[i] == nums[i - 1] + nums[i - 2]:
                cur += 1
            else:
                cur = 2
            best = max(best, cur)
        return best

