class Solution {
public:
    int longestFibonacciSubarray(vector<int>& nums) {
        int best = 2, cur = 2;
        for (int i = 2; i < (int)nums.size(); i++) {
            if ((long long)nums[i] == (long long)nums[i-1] + nums[i-2]) cur++;
            else cur = 2;
            best = max(best, cur);
        }
        return best;
    }
};

