class Solution {
    public int longestFibonacciSubarray(int[] nums) {
        int best = 2, cur = 2;
        for (int i = 2; i < nums.length; i++) {
            if (nums[i] == nums[i-1] + nums[i-2]) cur++;
            else cur = 2;
            best = Math.max(best, cur);
        }
        return best;
    }
}

